insert into programs (id, version, name, definition) values
  ('arnold-6day', 2, 'Arnold rolling six-day block', '{"id":"arnold-6day","version":2,"name":"Arnold rolling six-day block","blocks":9,"slots":[{"kind":"lift","key":"A"},{"kind":"lift","key":"B"},{"kind":"steady"},{"kind":"lift","key":"C"},{"kind":"lift","key":"D"},{"kind":"intervals"}],"phases":[{"id":"base","name":"Base","color":"#2F6BB0","kg":"20","from":0,"to":17,"note":"Straight sets, no intensity tricks. Hit the top of every rep range on every set before you add load."},{"id":"load","name":"Load","color":"#E5A912","kg":"15","from":18,"to":35,"note":"First lift drops to 6-8 reps and goes heavier. Drop sets come in on one nominated move per session."},{"id":"peak","name":"Peak","color":"#C93A2B","kg":"25","from":36,"to":53,"note":"Reps back up, drop sets stay, and the opening compound gets rest-pause. Expect to finish this phase ready for a week off."}],"tech":{"drop":{"label":"Drop set","when":"Final set only","steps":["Take the last set to the point where the next rep would stall.","Strip 25-30% of the load in under 10 seconds. On a stack, pin down 2-3 plates. Don''t sit down.","Go again to that same stall point. Expect roughly half the reps.","Blocks 4-5: one drop. Block 6 onward: two drops, 20-25% off each time."]},"rp":{"label":"Rest-pause","when":"Final set only","steps":["Take the last set to one rep short of failure, then rack it.","Stand and breathe for 15 seconds. About five slow breaths, no more.","Same weight, go again for whatever you get. Rack, 15 seconds, one more mini-set.","Expect roughly 8 / 4 / 2. If mini-set two beats half of set one, add load next time.","Machine, spotter, or safety pins. This is not the place to be brave."]}},"sessions":{"A":{"letter":"A","title":"Chest + Back","sub":"Every move paired","ex":[{"id":"incline-barbell-press","name":"Incline barbell press","sets":4,"reps":"8-10","rest":90,"pair":1,"loadReps":"6-8","tech":"rp"},{"id":"wide-grip-pulldown","name":"Wide-grip pull-up / pulldown","sets":4,"reps":"8-12","rest":90,"pair":1},{"id":"flat-db-press","name":"Flat dumbbell press","sets":3,"reps":"10-12","rest":75,"pair":2},{"id":"barbell-row","name":"Barbell row","sets":3,"reps":"10","rest":75,"pair":2},{"id":"cable-fly","name":"Cable fly","sets":3,"reps":"12-15","rest":60,"pair":3,"tech":"drop"},{"id":"seated-cable-row","name":"Seated cable row","sets":3,"reps":"12","rest":60,"pair":3},{"id":"dips","name":"Dips","sets":2,"reps":"AMRAP","rest":60,"pair":4},{"id":"straight-arm-pulldown","name":"Straight-arm pulldown","sets":2,"reps":"15","rest":60,"pair":4}]},"B":{"letter":"B","title":"Legs","sub":"Heavy work first, then paired","ex":[{"id":"back-squat","name":"Back squat","sets":4,"reps":"8-10","rest":90,"pair":null,"loadReps":"6-8"},{"id":"leg-press","name":"Leg press","sets":3,"reps":"12-15","rest":75,"pair":null,"tech":"rp"},{"id":"romanian-deadlift","name":"Romanian deadlift","sets":3,"reps":"10","rest":90,"pair":null},{"id":"leg-extension","name":"Leg extension","sets":3,"reps":"15","rest":60,"pair":1,"tech":"drop"},{"id":"lying-leg-curl","name":"Lying leg curl","sets":3,"reps":"12","rest":60,"pair":1},{"id":"standing-calf-raise","name":"Standing calf raise","sets":4,"reps":"15-20","rest":60,"pair":2},{"id":"hanging-knee-raise","name":"Hanging knee raise","sets":4,"reps":"12","rest":60,"pair":2}]},"C":{"letter":"C","title":"Shoulders + Arms","sub":"Delts first, arms in pairs","ex":[{"id":"arnold-press","name":"Arnold press","sets":4,"reps":"8-10","rest":90,"pair":null,"loadReps":"6-8","tech":"rp"},{"id":"lateral-raise","name":"Lateral raise","sets":4,"reps":"12-15","rest":60,"pair":1,"tech":"drop"},{"id":"rear-delt-fly","name":"Rear delt fly","sets":4,"reps":"15","rest":60,"pair":1},{"id":"cable-upright-row","name":"Cable upright row","sets":3,"reps":"12","rest":60,"pair":null},{"id":"barbell-curl","name":"Barbell curl","sets":3,"reps":"10","rest":75,"pair":2},{"id":"close-grip-bench","name":"Close-grip bench","sets":3,"reps":"10","rest":75,"pair":2},{"id":"incline-db-curl","name":"Incline dumbbell curl","sets":3,"reps":"12","rest":60,"pair":3},{"id":"rope-pushdown","name":"Rope pushdown","sets":3,"reps":"12-15","rest":60,"pair":3},{"id":"hammer-curl","name":"Hammer curl","sets":2,"reps":"12","rest":60,"pair":4},{"id":"overhead-cable-ext","name":"Overhead cable extension","sets":2,"reps":"12","rest":60,"pair":4}]},"D":{"letter":"D","title":"Chest + Back","sub":"Pump work, new angles","ex":[{"id":"weighted-dips","name":"Weighted dips / decline press","sets":4,"reps":"10-12","rest":75,"pair":1,"loadReps":"8-10","tech":"rp"},{"id":"chest-supported-row","name":"Chest-supported row","sets":4,"reps":"10-12","rest":75,"pair":1},{"id":"db-pullover","name":"Dumbbell pullover","sets":3,"reps":"12","rest":60,"pair":2},{"id":"face-pull","name":"Face pull","sets":3,"reps":"15","rest":60,"pair":2},{"id":"incline-db-fly","name":"Incline dumbbell fly","sets":3,"reps":"12-15","rest":60,"pair":3,"tech":"drop"},{"id":"single-arm-pulldown","name":"Single-arm lat pulldown","sets":3,"reps":"12 / side","rest":60,"pair":3},{"id":"ez-curl","name":"EZ-bar curl","sets":2,"reps":"15","rest":60,"pair":4},{"id":"triceps-pushdown","name":"Triceps pushdown","sets":2,"reps":"15","rest":60,"pair":4},{"id":"cable-crunch","name":"Cable crunch","sets":3,"reps":"15","rest":60,"pair":null}]}},"modes":{"run":{"label":"Run","protocol":"6 x 3 min hard / 90 s jog","unit":"km"},"rower":{"label":"Rower","protocol":"8 x 30 s hard / 90 s easy","unit":"m"},"ski":{"label":"Ski erg","protocol":"8 x 30 s hard / 90 s easy","unit":"m"},"bike":{"label":"Bike","protocol":"8 x 30 s hard / 90 s easy","unit":"km"}}}'::jsonb)
